root = os.path.join(os.path.dirname(__file__), '..', 'kb')
for slug, screen, module, roles, *langs in A:
    for lang, (title, steps) in zip(['en', 'hi', 'te'], langs):
        os.makedirs(os.path.join(root, lang), exist_ok=True)
        lines = ['---', f'slug: {slug}', f'title: "{title}"', f'screen: {screen}']
        if module:
            lines.append(f'module: {module}')
        if roles:
            lines.append(f'roles: [{", ".join(roles)}]')
        lines += ['---', '']
        lines += [f'{i + 1}. {s}' for i, s in enumerate(steps)]
        with open(os.path.join(root, lang, f'{slug}.md'), 'w', encoding='utf-8') as f:
            f.write('\n'.join(lines) + '\n')
print(len(A), 'articles x 3 languages')
